  const themeColors = {'dark':'#050505', 'light':'#f6f7f9', 'slate':'#111720', 'classic-sage-mustard':'#E8EFE2', 'warm-neutral':'#FDF8EE', 'modern-minimal':'#F3F6EF', 'deep-rich':'#243225', 'sage-blush':'#F9EFEF', 'sage-navy':'#E9EFE8', 'sage-terracotta':'#F7EEE8', 'sage-cream':'#FFFDF6', 'sage-charcoal':'#F6F7F4', 'mustard-forward':'#FFF5D6', 'sage-teal':'#E8F3F0', 'sage-lavender':'#F4F0FA', 'warm-earthy':'#FDF8EE', 'soft-airy':'#FFF9F0', 'earthy-neutral':'#F7EFE4', 'muted-luxury':'#E6E8D9'};
