    const catalogRequest=e.target.closest('[data-catalog-request]'); if(catalogRequest){ const form=document.getElementById('requestForm'); if(form){ form.elements.item_name.value=catalogRequest.dataset.itemName||''; form.elements.category.value=catalogRequest.dataset.itemCategory||''; form.elements.unit.value=catalogRequest.dataset.itemUnit||'unit'; } openModal('requestModal'); prepareRequestBalance(); }
